// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    address deployer;

    function setUp() public {
        deployer = address(this);
        c = new Owned();
    }

    function testFuzz_property(address actor, address newOwner) public {
        vm.assume(actor != address(0));
        bool ok;
        vm.prank(actor);
        try c.setOwner(newOwner) {
            ok = true;
        } catch {
            ok = false;
        }
        // General rule: c.owner() may only change when the caller is the initial owner (deployer).
        assertTrue(!ok || actor == deployer, "unauthorized owner change");
    }
}
